# Posts the latest article to the QureVanta Facebook Page via the Meta Graph API:
# a 1080x1350 image (article photo + dark overlay + bold title, generated by Cloudinary)
# with a short caption and the article link.
#
# Input:  automation/logs/latest-article.json  (written by the daily article run)
#         { "slug": "...", "socialTitle": "...", "caption": "..." }
# Secrets: %USERPROFILE%\.qurevanta\facebook.json  (never committed)
#         { "pageId": "...", "pageToken": "..." }
# Usage:  powershell -File post-to-facebook.ps1 [-DryRun]

param([switch]$DryRun)
$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent $PSScriptRoot
$logDir = Join-Path $PSScriptRoot 'logs'
$graphVersion = 'v23.0'

function Escape-CloudinaryText([string]$text) {
  $encoded = [uri]::EscapeDataString($text)
  return $encoded.Replace('%2C', '%252C').Replace('%2F', '%252F').Replace('%3A', '%253A')
}

function Get-SocialImageUrl([string]$imageUrl, [string]$title, [string]$category) {
  $layers = @(
    'c_fill,g_auto,w_1080,h_1350',
    'co_rgb:000000,e_colorize:62',
    "l_text:Montserrat_34_bold_letter_spacing_6:$(Escape-CloudinaryText $category.ToUpper()),co_rgb:D4F26D/fl_layer_apply,g_north_west,x_80,y_110",
    "l_text:Montserrat_84_bold_line_spacing_-6:$(Escape-CloudinaryText $title),co_white,c_fit,w_920/fl_layer_apply,g_west,x_80,y_-40",
    "l_text:Montserrat_34:$(Escape-CloudinaryText 'Read the full guide'),co_rgb:C9D6CF/fl_layer_apply,g_south_west,x_80,y_150",
    "l_text:Montserrat_44_bold:$(Escape-CloudinaryText 'qurevanta.com'),co_rgb:D4F26D/fl_layer_apply,g_south_west,x_80,y_85",
    'f_jpg,q_auto'
  ) -join '/'
  if ($imageUrl -match '^https://res\.cloudinary\.com/dr3ie9gpz/image/upload/(?:[^/]*_[^/]*/)*(v\d+/.+)$') {
    return "https://res.cloudinary.com/dr3ie9gpz/image/upload/$layers/$($Matches[1])"
  }
  # Image hosted elsewhere (e.g. Unsplash fallback): let Cloudinary fetch it
  return "https://res.cloudinary.com/dr3ie9gpz/image/fetch/$layers/$([uri]::EscapeDataString($imageUrl))"
}

$info = Get-Content (Join-Path $logDir 'latest-article.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$articlePath = Join-Path $repo "src\content\blog\$($info.slug).md"
$front = @{}
foreach ($line in (Get-Content $articlePath -Encoding UTF8)) {
  if ($line -eq '---' -and $front.Count) { break }
  if ($line -match '^(\w+):\s*(.*)$') { $front[$Matches[1]] = $Matches[2] }
}
$articleUrl = "https://www.qurevanta.com/resources/$($info.slug)"
$title = if ($info.socialTitle) { $info.socialTitle } else { $front['title'] }
$imageUrl = Get-SocialImageUrl $front['image'] $title $front['category']
$pointer = [char]::ConvertFromUtf32(0x1F449)  # pointing-hand emoji (kept out of the file for PowerShell 5.1)
$caption = "$($info.caption.Trim())`n`n$pointer Read the full guide: $articleUrl"

# Make sure the image renders before posting
$img = Invoke-WebRequest -Uri $imageUrl -Method Head -UseBasicParsing
Write-Output "Image OK ($($img.StatusCode)): $imageUrl"

if ($DryRun) {
  Write-Output "DRY RUN - would post:`n$caption"
  return
}

$postedMarker = Join-Path $logDir 'facebook-posted.txt'
if ((Test-Path $postedMarker) -and ((Get-Content $postedMarker) -contains $info.slug)) {
  Write-Output "Already posted $($info.slug) to Facebook."
  return
}

$secretsFile = Join-Path $env:USERPROFILE '.qurevanta\facebook.json'
if (-not (Test-Path $secretsFile)) { throw "Facebook credentials not found at $secretsFile" }
$secrets = Get-Content $secretsFile -Raw | ConvertFrom-Json

# Wait until Vercel has deployed the article (up to ~10 minutes)
for ($i = 0; $i -lt 40; $i++) {
  try { if ((Invoke-WebRequest -Uri $articleUrl -Method Head -UseBasicParsing).StatusCode -eq 200) { break } } catch { }
  Start-Sleep -Seconds 15
}

# Send as UTF-8 form data so emoji and punctuation in the caption survive
$form = @{ url = $imageUrl; caption = $caption; published = 'true'; access_token = $secrets.pageToken }
$body = ($form.GetEnumerator() | ForEach-Object { "$($_.Key)=$([uri]::EscapeDataString($_.Value))" }) -join '&'
$response = Invoke-RestMethod -Method Post -Uri "https://graph.facebook.com/$graphVersion/$($secrets.pageId)/photos" `
  -ContentType 'application/x-www-form-urlencoded; charset=utf-8' -Body ([System.Text.Encoding]::UTF8.GetBytes($body))
Add-Content -Path $postedMarker -Value $info.slug
Write-Output "Posted to Facebook: post id $($response.post_id)"
